local k, val = v:match('^([^:]+):%s*(.*)$')
if not k or val == '' then return nil end
return { name = (k:gsub('^%s*(.-)%s*$', '%1')), value = (val:gsub('%s+', ' '):gsub('^%s*(.-)%s*$', '%1')) }

local l, w, h, u = v:match('([%d%.]+)%s*x%s*([%d%.]+)%s*x%s*([%d%.]+)%s*(%a+)')
if not l then return nil end
return { length = tonumber(l), width = tonumber(w), height = tonumber(h), unit = u }

local n, u = v:match('([%d%.]+)%s*(%a+)')
if not n then return nil end
return { value = tonumber(n), unit = u }
